def frontend(self, path: str, directory: str):
    import os
    from starlette.responses import FileResponse

    async def serve_frontend(request):
        path_prefix = path.rstrip('/')
        full_path = request.url.path
        if path_prefix and full_path.startswith(path_prefix):
            relative_path = full_path[len(path_prefix):].lstrip('/')
        else:
            relative_path = full_path.lstrip('/')
        file_path = os.path.join(directory, relative_path)
        if os.path.isfile(file_path):
            return FileResponse(file_path)
        return FileResponse(os.path.join(directory, "index.html"))

    route_path = f"{path.rstrip('/')}/{{full_path:path}}"
    if path == "/":
        route_path = "/{full_path:path}"
    self.add_api_route(route_path, serve_frontend)

